// Independent NAV6 packet oracle; no expected topology is generated by the walker.
@Test func snapshotV12IndependentMixedOracleMatchesEveryRecord() throws {
    let text = "{\n  \"\": {\"0\": [null, {\"id\": 9007199254740993, \"amount\": 0.0100}]},\n  \"0\": [\"numeric object key, not index\"],\n  \"é\": \"composed\",\n  \"é\": \"decomposed\",\n  \"rows\": [\n    {\"z\": null, \"a\": 1},\n    {\"a\": 2},\n    {},\n    {\"b\": 3, \"a\": 4},\n    false\n  ],\n  \"matrix\": [[0.1, 2], [3]]\n}\n"
    let result = try JSONStructuralSnapshotBuilder(document: JSONParser().parseDocument(Data(text.utf8))).build().result
    let expected: [(Int?, JSONLocationComponent?, JSONTraversalKind, Int, Int, Int)] = [
        (nil, nil, .object, 0, 6, 28),
        (0, .key(""), .object, 1, 1, 7),
        (1, .key("0"), .array, 2, 2, 7),
        (2, .index(0), .null, 3, 0, 4),
        (2, .index(1), .object, 3, 2, 7),
        (4, .key("id"), .number, 4, 0, 6),
        (4, .key("amount"), .number, 4, 0, 7),
        (0, .key("0"), .array, 1, 1, 9),
        (7, .index(0), .string, 2, 0, 9),
        (0, .key("é"), .string, 1, 0, 10),
        (0, .key("é"), .string, 1, 0, 11),
        (0, .key("rows"), .array, 1, 5, 22),
        (11, .index(0), .object, 2, 2, 15),
        (12, .key("z"), .null, 3, 0, 14),
        (12, .key("a"), .number, 3, 0, 15),
        (11, .index(1), .object, 2, 1, 17),
        (15, .key("a"), .number, 3, 0, 17),
        (11, .index(2), .object, 2, 0, 18),
        (11, .index(3), .object, 2, 2, 21),
        (18, .key("b"), .number, 3, 0, 20),
        (18, .key("a"), .number, 3, 0, 21),
        (11, .index(4), .boolean, 2, 0, 22),
        (0, .key("matrix"), .array, 1, 2, 28),
        (22, .index(0), .array, 2, 2, 26),
        (23, .index(0), .number, 3, 0, 25),
        (23, .index(1), .number, 3, 0, 26),
        (22, .index(1), .array, 2, 1, 28),
        (26, .index(0), .number, 3, 0, 28),
    ]
    #expect(result.recordCount == expected.count)
    for ordinal in expected.indices {
        let record = try result.record(at: ordinal), want = expected[ordinal]
        #expect(record.ordinal == ordinal && record.parentOrdinal == want.0)
        #expect(record.componentFromParent == want.1 && record.kind == want.2)
        #expect(record.depth == want.3 && record.childCount == want.4 && record.subtreeEndExclusive == want.5)
    }
}

private enum TransferMarker: Error { case afterTransfer }
private struct TransferProbe: JSONTraversalOwnedReducer {
    enum Mode: Sendable { case twice, work, caller, cancellation }
    let mode: Mode
    mutating func observe(_ hit: JSONTraversalHit, value: JSON,
                          context: inout JSONTraversalContext) throws -> JSONTraversalAction { .continue }
    mutating func finish(_ summary: JSONTraversalSummary,
                         context: inout JSONTraversalContext) throws -> JSONDocument {
        let document = try context.transferDocumentOwnership()
        switch mode {
        case .twice:
            do { _ = try context.transferDocumentOwnership() } catch { }
        case .work:
            do { try context.work(64_000_000) } catch { }
        case .cancellation:
            withUnsafeCurrentTask { $0?.cancel() }
            do { try context.checkpoint() } catch { }
        case .caller: throw TransferMarker.afterTransfer
        }
        // Success/replacement cannot mask a terminal failure latched after transfer.
        if mode == .twice { return document }
        throw TransferMarker.afterTransfer
    }
}

@Test func snapshotV20TransferFailureCannotPublishAndScopeAlwaysInvalidates() async throws {
    let document = try JSONParser().parseDocument(Data("[null]".utf8))
    for mode in [TransferProbe.Mode.twice, .work, .caller, .cancellation] {
        let invalidated = Mutex(false)
        let task = Task { @Sendable [document, mode] in
            var walk = JSONTraversal(document: document)
            walk.lifetimeObserver = { rootGone, stateGone in invalidated.withLock { $0 = rootGone && stateGone } }
            var probe = TransferProbe(mode: mode)
            return try walk.inspectOwned(reducer: &probe)
        }
        do { _ = try await task.value; Issue.record("No post-transfer failure may publish a report") }
        catch let error as JSONFailure {
            if mode == .twice { #expect(error.category == .configuration && error.code == .invalidOperation) }
            else { #expect(mode == .work && error.resource?.metric == .workUnits) }
        }
        catch is CancellationError { #expect(mode == .cancellation) }
        catch is TransferMarker { #expect(mode == .caller) }
        #expect(invalidated.withLock { $0 })
    }
    // Ordinary read/visit/N2 have no ownership transfer: their refunds are unchanged.
    #expect(try document.readWithReport { _ in true }.statistics[.retainedBytes] == 0)
    #expect(try JSONTraversal(document: document).visit { _, _ in .continue }.statistics[.retainedBytes] == 0)
    let shape = try JSONShapeInspector(document: document).inspectArray()
    #expect(shape.statistics[.retainedBytes] == 256)
}

@Test func snapshotV22ConcurrentLookupsUseIndependentAdmissionAndHealth() async throws {
    let document = try JSONParser().parseDocument(Data(#"{"x":[null,9007199254740993]}"#.utf8))
    let snapshot = try JSONStructuralSnapshotBuilder(document: document).build().result
    let baseline = try snapshot.value(for: 3)
    try await withThrowingTaskGroup(of: UInt64.self) { group in
        for ordinal in 0..<16 { group.addTask {
            if ordinal.isMultiple(of: 2) {
                var limits = JSONLimits.balanced; limits[.nodes] = 0
                do { _ = try snapshot.value(for: 3, limits: limits); Issue.record("Expected source-admission refusal") }
                catch let error as JSONFailure { #expect(error.resource?.metric == .nodes) }
            }
            let value = try snapshot.value(for: 3)
            #expect(value.result == baseline.result)
            #expect(value.statistics[.nodes] == UInt64(snapshot.recordCount))
            #expect(try snapshot.location(for: 3).result == [.key("x"), .index(1)])
            #expect(try snapshot.sourceSpan(for: 3).result != nil)
            return value.statistics[.workUnits]
        } }
        for try await work in group { #expect(work == baseline.statistics[.workUnits]) }
    }
}
